    int n = 42;
    int m = 38;

    double A[42][38];
    double s[38];
    double q[42];
    double p[38];
    double r[42];

    init_array(m, n, A, r, p);

    kernel_bicg(A, s, q, p, r);

    print_array(m, n, s, q);

    return 0;
}
