#include "bicg.h"

void kernel_bicg(
    double A[42][38],
    double s[38],
    double q[42],
    double p[38],
    double r[42])
{
    // Compute q = A * p
    for (int i = 0; i < 42; i++) {
        q[i] = 0.0;
        for (int j = 0; j < 38; j++) {
            q[i] += A[i][j] * p[j];
        }
    }

    // Compute s = A^T * r
    for (int j = 0; j < 38; j++) {
        s[j] = 0.0;
        for (int i = 0; i < 42; i++) {
            s[j] += A[i][j] * r[i];
        }
    }
}

